F1,F2,F3,F4,F5=WIDE
tool_html=r'''<div class="ir-tool" id="ir-tool"><style>.ir-tc-h{margin:1.1rem 0 .3rem;font-weight:700}.ir-tc-p{margin:.2rem 0 .6rem;font-size:.9rem;opacity:.9}.ir-tc-btns{display:flex;gap:.5rem;flex-wrap:wrap;margin:.4rem 0}.ir-tc-btns button{min-width:0!important;flex:1 1 150px}.ir-cmp{display:grid;grid-template-columns:minmax(96px,1fr) 2fr 2fr;gap:.3rem .75rem;margin-top:.75rem;font-size:.88rem}.ir-cmp span{overflow-wrap:anywhere}.ir-cmp .k{opacity:.75}.ir-cmp .h{font-weight:700}.ir-tc-verdict{margin:.75rem 0 0;font-weight:700}.ir-fo-log{margin:.6rem 0 0;padding:.6rem .8rem;border:1px solid color-mix(in srgb,currentColor 18%,transparent);border-radius:8px;font:inherit;font-family:var(--font-mono,ui-monospace,Menlo,Consolas,monospace);font-size:.8rem;white-space:pre-wrap;overflow-wrap:anywhere;max-height:14rem;overflow:auto}</style><div class="ir-tool-head"><span class="ir-tool-eyebrow">Two-connection check</span></div>
<p class="ir-tc-h">1. Compare two connections</p><p class="ir-tc-p">Read this connection as A. Then switch to your other line, for example by unplugging the first, joining the other router's Wi-Fi or turning on a phone hotspot, and read it as B.</p><div class="ir-tc-btns"><button type="button" class="ir-btn-primary" id="ir-tc-a">Read connection A</button><button type="button" class="ir-btn-primary" id="ir-tc-b">Read connection B</button><button type="button" class="ir-btn-secondary" id="ir-tc-clear">Clear</button></div><div id="ir-tc-cmp" aria-live="polite"></div>
<p class="ir-tc-h">2. Test failover</p><p class="ir-tc-p">Keep this device on your router's Wi-Fi or LAN and turn off mobile data on a phone. Start the test, then unplug your primary line. It runs for up to 5 minutes.</p><div class="ir-tc-btns"><button type="button" class="ir-btn-primary" id="ir-fo-start">Start failover test</button><button type="button" class="ir-btn-secondary" id="ir-fo-stop" disabled>Stop</button></div><div id="ir-fo-out" aria-live="polite"></div>
<p class="ir-tool-note">Readings stay in this tab only. The check uses the same lookup as the IP address guide, and the failover test also contacts public endpoints to see whether you are online. Nothing is stored by IntelReap.</p></div>'''
tool_js=r'''<script src="../assets/js/config.js"></script>
<script>(function(){var ba=document.getElementById('ir-tc-a'),bb=document.getElementById('ir-tc-b'),bc=document.getElementById('ir-tc-clear'),cmp=document.getElementById('ir-tc-cmp'),bs=document.getElementById('ir-fo-start'),bx=document.getElementById('ir-fo-stop'),fo=document.getElementById('ir-fo-out');if(!ba||!bb||!bc||!cmp||!bs||!bx||!fo||typeof NDIC_CONFIG==='undefined')return;
function e(s){return String(s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function call(ep){var c=new AbortController(),t=setTimeout(function(){c.abort()},10000);return fetch(NDIC_CONFIG.BACKEND_URL+ep,{signal:c.signal,cache:'no-store'}).then(function(r){clearTimeout(t);if(!r.ok)throw 0;return r.json()},function(x){clearTimeout(t);throw x}).then(function(j){if(!j||!j.success||!j.data)throw 0;return j.data})}
function readId(){return call(NDIC_CONFIG.ENDPOINTS.ipIdentity)}
function reading(){return Promise.all([readId(),call(NDIC_CONFIG.ENDPOINTS.ipDeep).catch(function(){return{}})]).then(function(r){var i=r[0],d=r[1];return{ip:String(i.ip||''),isp:String(i.isp||''),org:String(i.org||''),type:String(i.connectionType||''),asn:d.asnNumber!=null?String(d.asnNumber):'',owner:String(d.asnOwner||''),up:String(d.upstreamProvider||''),mobile:d.isMobile===true?'Yes':(d.isMobile===false?'No':'')}})}
var R={a:null,b:null};try{var sv=JSON.parse(sessionStorage.getItem('ir-tc')||'null');if(sv&&typeof sv==='object'){R.a=sv.a||null;R.b=sv.b||null}}catch(x){}
function save(){try{sessionStorage.setItem('ir-tc',JSON.stringify(R))}catch(x){}}
var FLD=[['Public IP','ip'],['ISP','isp'],['Organisation','org'],['Network owner','owner'],['Network number','asn'],['Upstream provider','up'],['Mobile network','mobile'],['Connection type','type']];
function same(x,y){return !!x&&!!y&&x.toLowerCase()===y.toLowerCase()}
function verdict(a,b){var v;if(same(a.ip,b.ip)){v='Same public address: both readings came through the same line, or the router did not switch.'}else{var ka=a.asn&&b.asn?[a.asn,b.asn]:(a.owner&&b.owner?[a.owner,b.owner]:(a.isp&&b.isp?[a.isp,b.isp]:null));
if(!ka)v='Different public addresses, but the provider networks could not be compared.';else if(same(ka[0],ka[1]))v='Different addresses on the same provider network: two addresses from one provider, which is not independent redundancy.';else if(same(a.up,b.up))v='Different provider networks that share an upstream provider: independence is limited.';else v='Different provider networks: the two lines look independent at the provider level. This does not prove they use separate physical lines.'}
if(a.mobile==='Yes')v+=' Connection A is on a mobile network.';if(b.mobile==='Yes')v+=' Connection B is on a mobile network.';return v}
function render(){if(!R.a&&!R.b){cmp.textContent='';return}var h='<div class="ir-cmp"><span class="h"></span><span class="h">Connection A</span><span class="h">Connection B</span>';FLD.forEach(function(f){h+='<span class="k">'+e(f[0])+'</span><span>'+e((R.a&&R.a[f[1]])||'-')+'</span><span>'+e((R.b&&R.b[f[1]])||'-')+'</span>'});h+='</div>';if(R.a&&R.b)h+='<p class="ir-tc-verdict">'+e(verdict(R.a,R.b))+'</p>';else h+='<p class="ir-tool-note">Now switch to your other line and read it as '+(R.a?'B':'A')+'.</p>';cmp.innerHTML=h}
function take(k,btn){btn.disabled=true;var old=btn.textContent;btn.textContent='Reading...';reading().then(function(r){R[k]=r;save();render()}).catch(function(){cmp.innerHTML='<p class="ir-tool-note">Could not read this connection. Check that you are online and try again.</p>'}).then(function(){btn.disabled=false;btn.textContent=old})}
ba.addEventListener('click',function(){take('a',ba)});bb.addEventListener('click',function(){take('b',bb)});bc.addEventListener('click',function(){R={a:null,b:null};save();render()});render();
/* failover test: reachability through public endpoints, backend only at start, after recovery and a slow re-check */
var P=['https://www.cloudflare.com/cdn-cgi/trace','https://api.ipify.org?format=json'],F={run:false,t:null,base:null,down:false,tDown:0,start:0,idN:0,lastId:0,log:[]};
function one(u){var c=new AbortController(),t=setTimeout(function(){c.abort()},4000);return fetch(u,{method:'HEAD',mode:'no-cors',cache:'no-store',signal:c.signal}).then(function(){clearTimeout(t);return true},function(){clearTimeout(t);return false})}
function probe(){return one(P[0]).then(function(ok){return ok||one(P[1])})}
var pre=document.createElement('pre');pre.className='ir-fo-log';pre.hidden=true;var sm=document.createElement('p');sm.className='ir-tc-verdict';fo.appendChild(pre);fo.appendChild(sm);
function log(m){F.log.push('+'+Math.round((Date.now()-F.start)/1000)+' s  '+m);pre.hidden=false;pre.textContent=F.log.join('\n');pre.scrollTop=pre.scrollHeight}
function end(m){F.run=false;clearTimeout(F.t);bs.disabled=false;bx.disabled=true;sm.textContent=m}
function desc(i){return i.ip+(i.isp?' ('+i.isp+')':'')}
function judge(secs,n){var a=F.base,m=n.ip!==a.ip;end(m?(secs>0?'Failover worked: the connection came back after about '+secs+' s on a different public address, '+desc(a)+' to '+desc(n)+'. Timing is accurate to within a few seconds.':'The public address changed with no measurable loss of connection, '+desc(a)+' to '+desc(n)+'. That looks like a fast failover.'):'The connection came back on the same public address. Either the primary line returned, or the router switched to a line with the same address.')}
function recover(secs,tries){readId().then(function(n){if(!F.run)return;log('Address now '+desc(n));judge(secs,n)}).catch(function(){if(!F.run)return;if(tries<3){F.t=setTimeout(function(){recover(secs,tries+1)},2000)}else end('The connection came back, but the new address could not be read. Run the test again.')})}
function tick(){if(!F.run)return;if(Date.now()-F.start>300000){end('No loss of connection was detected within 5 minutes. If your router switches lines faster than the check interval, the address change is the only sign.');return}
probe().then(function(ok){if(!F.run)return;
if(!ok&&!F.down){F.down=true;F.tDown=Date.now();log('Connection lost')}
else if(ok&&F.down){F.down=false;var s=Math.round((Date.now()-F.tDown)/1000);log('Connection back after about '+s+' s');recover(s,1);return}
else if(ok&&F.idN<10&&Date.now()-F.lastId>30000){F.lastId=Date.now();F.idN++;readId().then(function(n){if(F.run&&n.ip!==F.base.ip){log('Public address changed to '+desc(n));judge(0,n)}}).catch(function(){})}
F.t=setTimeout(tick,3000)})}
bs.addEventListener('click',function(){if(F.run)return;F={run:true,t:null,base:null,down:false,tDown:0,start:Date.now(),idN:0,lastId:0,log:[]};sm.textContent='';pre.textContent='';bs.disabled=true;bx.disabled=false;log('Reading the starting address');
readId().then(function(i){if(!F.run)return;F.base=i;F.lastId=Date.now();log('Starting address '+desc(i)+'. Unplug your primary line now.');tick()}).catch(function(){end('Could not read the starting address. Check that you are online and try again.')})});
bx.addEventListener('click',function(){if(F.run){log('Stopped');end('Stopped.')}})})();</script>'''
S=dict(slug='can-you-have-two-isps-in-one-house',date='2026-06-24',date_label='',plan='A5',tool_html=tool_html,tool_js=tool_js,
title='Can You Have Two Internet Providers in One House?',headline='Can You Have Two Internet Providers in One House? How It Works, Setups, Failover and a Connection Check',
desc='Yes, if both providers reach your address. See one-router and two-router setups, failover vs load balancing, and compare your connections with a free check.',
kw=['can you have two internet providers in one house','can you have two isps in one house','can i have 2 isp in one house','two internet providers one router','can i have two internet providers at the same time','dual isp','secondary isp','dual wan router','isp failover','isp load balancing','two internet providers in an apartment','can you have two fiber internet in a house'],about='Two internet providers',section='Network Guides',crumb='Two Internet Providers',
h1='Can You Have <span class="ndic-highlight">Two Internet Providers</span> in One House?',tagline='How two providers work in one home, whether to use one router or two, and how to test that your backup line really works.',kicker='Network Guides',cta='Check My Connections',
qa_title='Yes, if both can reach your address',
qa_body='Yes, if both providers can reach your address. To use both on one network you need a router with two WAN connections (dual WAN), set to failover or load balancing. Two lines do not double a single download. Use the check below to compare your connections and test failover.',
og_title='Two Internet <span style="color:#38bdf8">Providers</span>',og_sub='One house, two lines: how it works',og_chip='ISP A <span style="color:#38bdf8">+</span> ISP B',
card_desc='Yes, if both providers reach your address. See one-router and two-router setups, failover vs load balancing, and compare your connections with a free check.',
panel=dict(eyebrow='Network Route panel',h3='Check which provider each line comes from',p='The two-connection check reads the basics. The <a href="/intelligence/network-route">Network Route panel</a> shows the network number, owner and upstream provider for the connection you are on.',href='/intelligence/network-route',btn='Open Network Route'),
sections=[
('yes','Yes, and You May Already Have Two Connections',r'''<p>Yes. Subscribing to two internet providers at one address is possible. The practical questions are whether both can reach your address and how you connect them. Your phone's mobile data is already a second connection of a kind. The rest of this page covers two home lines, used as a backup or used together.</p><p>Use the two-connection check above to see which provider each of your connections comes from, and to test whether failover works.</p>'''),
('allowed','Is It Allowed?',r'''<p>Check three things before you order: your lease or building rules on installing a second line, each provider's terms on sharing or reselling your connection, and whether your landlord or building manager has any arrangement with a provider. In the US, a cable franchising authority may not grant an exclusive franchise (47 U.S.C. §541), so a cable company cannot hold one by law, although what is built at your address still decides which providers are available. Other countries differ, so confirm locally.</p>'''),
('reach','Can a Second Provider Reach Your Address?',r'''<p>In the US, the FCC's National Broadband Map lists the providers that report service at an address, with the technology and speeds they report. The data comes from providers, and the FCC provides a way to challenge it. In the UK, Ofcom's broadband and mobile coverage checker shows what services are available at a postcode, and names providers only where they have given permission. Elsewhere, ask providers directly.</p><p>A map entry is not a line installed at your door. Ask each provider whether it will install its own line, and whether it uses the same underlying network as your current provider, because two brands can share one line.</p>'''),
('setups','One Router or Two',r'''<p>A home router normally has one WAN port, where a single provider's modem or ONT connects. To use two providers on one network, the router must support two WAN connections, often called dual WAN or multi-WAN. Without that, the practical choices are two routers on two separate networks, or a phone hotspot as a manual backup.</p>'''+fig(F1,'')+table('The three setups',['Setup','Result','Switches automatically?','Needs'],[['Dual-WAN router','One network, failover or sharing','Yes, in failover or load balancing mode','A router with dual WAN'],['Two routers','Two separate networks','No, each device uses the network it joins','Two routers'],['Phone hotspot','A manual backup','No','A phone data plan']])),
('modes','Failover or Load Balancing',r'''<p>Dual-WAN routers offer two main modes. In failover, one line carries traffic and the router switches to the other when a check on the first fails, and some routers can switch back when it recovers. ASUS and TP-Link both describe failover and load balancing, and TP-Link calls failover Link Backup. The router decides a line is down with a check: ASUS uses a DNS query or a ping to the default gateway or to an address you choose.</p>'''+fig(F2,'')+r'''<p>In load balancing, the router assigns connections to the two lines by a ratio. ASUS gives 3:1 as an example, and TP-Link uses weights. Load balancing spreads many connections across both lines. It does not merge them into one faster line.</p>'''+fig(F3,'')+r'''<p>If your speed already swings before you add a second line, read <a href="/learn/why-does-my-internet-speed-fluctuate">why internet speed fluctuates</a> first.</p>'''),
('speed','Why Two Lines Do Not Double One Download',r'''<p>RFC 8684 states that ordinary TCP communication is restricted to a single path per connection. A single download therefore uses one line at a time, while many connections at once can use both. Multipath TCP, the subject of that RFC, lets one connection use several paths, but it needs support on both ends, and an ordinary website download does not have it.</p>'''+fig(F4,'')),
('routers','Routers That Support Two Connections',r'''<p>Check your router's specification page for dual WAN or multi-WAN before you buy. Two vendors document it in detail.</p>'''+table('Dual-WAN support',['Vendor','Feature','Notes'],[['ASUS','Dual WAN','In stock firmware, off by default and model-specific. The second connection can be a WAN, USB or Ethernet LAN port. Offers failover and load balancing. Some ASUS FAQ versions list IPv4 limits, so check IPv6 support for your model.'],['TP-Link','Load Balancing and Link Backup on Omada gateways such as the ER605','Load balancing uses weights. Link Backup is the failover mode.'],['Other makers','Dual WAN or multi-WAN','Check the specification page for your model.']])),
('setup','Setting It Up and Testing It',r'''<ol><li>Connect each provider's modem or ONT to its own WAN connection on the router.</li><li>Open the router settings and enable dual WAN, then choose failover or load balancing.</li><li>Set the check the router uses to detect a failed line, such as a DNS query or a ping to a reliable address.</li><li>Read each connection with the check at the top of this page.</li><li>Run the failover test while you unplug the primary line.</li></ol>'''+fig(F5,'')+r'''<p>If you need the router's address for step 2, <a href="/learn/find-router-ip-address">find your router's IP address</a> first.</p><p>The <a href="/intelligence/network-identity">Network Identity panel</a> shows which line you are on now, including any IPv6 address.</p><p>The <a href="/intelligence/live-network">Live Network panel</a> lets you compare latency, jitter and stability while each line is in use.</p>'''),
('terms','What Secondary ISP and Dual WAN Mean',r'''<p>Several names describe the same ideas.</p>'''+table('Terms',['Term','Meaning'],[['Secondary ISP','A second provider used as a backup or alongside the first'],['Dual WAN or multi-WAN','A router feature that accepts two or more internet connections'],['Failover (Link Backup)','Switching to the backup line when the primary fails'],['Load balancing','Assigning connections to both lines by a ratio'],['Failback','Returning to the primary line when it recovers']])),
('side','Costs and Side Effects',r'''<p>You pay for two services, and a backup line only helps if it is independent of the first. When failover switches lines, your public IP address changes, so open sessions such as VPN tunnels, remote desktop and game connections will usually drop and reconnect. Port forwarding and remote access to your home may also stop working on the backup line. The failover test shows the new address so you can see this for yourself.</p><p>Public and private addresses are explained in <a href="/learn/what-is-an-ip-address">What Is an IP Address?</a></p>'''),
],
logic="Answer the question first, then separate three things that are often confused: whether a second provider can reach you, how to connect two lines, and what two lines actually do. Give a way to check that the lines are different providers and that failover works, instead of assuming it.",
method="The check reads your public IP and ISP from IntelReap's identity lookup, and the network number, owner, upstream provider and mobile flag from its network lookup, then compares two readings kept in this tab. The failover test checks that you are online through public endpoints every 3 seconds for up to 5 minutes, and reads your address from IntelReap at the start, every 30 seconds, and after the connection returns. Timing is accurate to within a few seconds. A different network owner does not prove two lines are physically separate. We did not test any router or a real failover; the tool logic was exercised in a browser with simulated responses. That a changed address drops open sessions is our reasoning, and the advice to ask whether two brands share one line is general practice, not sourced. That multipath TCP needs both ends is our reading of RFC 8684. Some ASUS FAQ language versions state IPv4 limits that we saw only in Italian and Polish.",
cites=[("ASUS: Dual WAN introduction and setup, Failover and Load Balance",'https://www.asus.com/support/FAQ/1011719'),("TP-Link: Differences between Load Balancing and Link Backup",'https://www.tp-link.com/us/document/13240'),("TP-Link Omada: Configure Link Backup on a gateway in standalone mode",'https://support.omadanetworks.com/eg/document/12979'),("TP-Link: Configure Link Backup on an Omada gateway via the controller",'https://www.tp-link.com/support/faq/4044'),("47 U.S.C. 541: General franchise requirements",'https://www.law.cornell.edu/uscode/text/47/541.html'),("FCC: How to use the National Broadband Map",'https://help.bdc.fcc.gov/hc/en-us/articles/10467446103579'),("FCC: Broadband data for consumers",'https://www.fcc.gov/BroadbandData/Consumers'),("Ofcom: Broadband and mobile coverage checker",'https://www.ofcom.org.uk/phones-and-broadband/coverage-and-speeds/Ofcom-checker'),("Ofcom: About the mobile and broadband checker",'https://checker.ofcom.org.uk/en-gb/about-checker'),("RFC 8684: TCP Extensions for Multipath Operation with Multiple Addresses",'https://datatracker.ietf.org/doc/html/rfc8684')],
faq_sub='Thirteen questions about using two internet providers in one home.',
faq=[("Can you have two internet providers in one house?","Yes, if both can reach your address. You can use them on one network with a dual-WAN router, on two separate networks with two routers, or keep one as a manual backup."),
("Can I use two ISPs on one router?","Only if the router supports two WAN connections, often called dual WAN or multi-WAN. A router with a single WAN port cannot use two providers at once."),
("Do I need two routers?","Not if you have a dual-WAN router. With two ordinary routers you get two separate networks, and each device uses the one it joins, with no automatic switching."),
("Will two providers double my speed?","No for a single download. RFC 8684 states that ordinary TCP is restricted to a single path per connection. Many connections at once can use both lines under load balancing."),
("What is the difference between failover and load balancing?","Failover keeps one line active and switches to the other when a check on the first fails. Load balancing assigns connections to both lines by a ratio, for example 3 to 1."),
("Does failover change my public IP address?","Yes, when traffic moves to a line from a different provider or connection, the public address changes. Open sessions such as VPN tunnels will usually need to reconnect. The failover test above shows the new address."),
("Is it allowed to have two internet providers?","Check your lease, building rules and each provider's terms. In the US, a cable franchising authority may not grant an exclusive franchise under 47 U.S.C. 541. Other countries differ, so confirm locally."),
("Can I have two providers in an apartment?","It depends on the building. Ask your landlord or building manager, then ask each provider whether it can install service at your unit. A map listing does not guarantee an installed line."),
("Can I have two fiber lines in one house?","Only if two providers can each serve the address. Ask each one whether it will install its own line or uses the same underlying network as the other."),
("What is a secondary ISP?","A second provider used as a backup or alongside your main one. Routers call the feature dual WAN, multi-WAN or, for failover, Link Backup."),
("Is a phone hotspot a second ISP?","It is a second connection through a mobile network. You can use it as a manual backup, and some routers, such as ASUS models with a USB port, can use a USB connection as a second WAN."),
("How do I check that my two connections are independent?","Use the two-connection check: read each connection and compare the network owner and upstream provider. A different owner suggests different providers, but it does not prove separate physical lines."),
("Can I get two plans from the same provider?","Only if the provider offers it. Two plans from one provider will not protect you from an outage on that provider's network."),
],
)
